 function studentAvatar(which='card'){
   const small=which==='topbar';
   const name=String(state.profile.name||'Student').trim();
   const initials=name.split(/\s+/).slice(0,2).map(w=>w[0]||'').join('').toUpperCase()||'ST';
   const size=small?'avatar avatar-sm':'avatar student-photo-avatar';
   const inner=state.profile.hasAvatar
     ? `<img src="/api/avatar?v=${Number(state.profile.avatarVersion||0)}" alt="${esc(name)} profile photo" class="student-avatar-image">`
     : esc(initials);
   return `<span class="${size} ${state.profile.hasAvatar?'has-photo':''}" ${small?'':'role="img" aria-label="Student photo"'}>${inner}</span>`;
 }
 async function prepareAvatar(file){
   if(!file || !['image/jpeg','image/png','image/webp'].includes(file.type))
     throw new Error('Choose a JPG, PNG or WebP image.');
   if(file.size>10*1024*1024)throw new Error('Choose an image smaller than 10 MB.');
   const url=URL.createObjectURL(file);
   try{
     const image=new Image();
     await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(new Error('Could not read the selected photo.'));image.src=url;});
     if(!image.naturalWidth||!image.naturalHeight)throw new Error('This image is invalid.');
     const scale=Math.min(1,720/Math.max(image.naturalWidth,image.naturalHeight));
     const canvas=document.createElement('canvas');
     canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));
     canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));
     const ctx=canvas.getContext('2d');
     if(!ctx)throw new Error('Image resizing is unavailable.');
     ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);
     ctx.drawImage(image,0,0,canvas.width,canvas.height);
     const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',0.86));
     if(!blob || blob.size>2*1024*1024)throw new Error('Photo is too large to save.');
     return blob;
   }finally{URL.revokeObjectURL(url);}
 }
 async function uploadStudentAvatar(file){
   try{
     const blob=await prepareAvatar(file);
     const r=await fetch('/api/avatar',{method:'POST',headers:{'Content-Type':'image/jpeg'},body:blob});
     const data=await r.json();
     if(!r.ok)throw new Error(data.error||'Photo upload failed.');
     state.profile.hasAvatar=true;state.profile.avatarVersion=data.avatarVersion;
     toast('Profile photo saved in SQLite.');render();
   }catch(error){toast(error.message||'Could not upload photo.');console.error(error);}
 }
 async function removeStudentAvatar(){
   try{
     const r=await fetch('/api/avatar',{method:'DELETE'}),data=await r.json();
     if(!r.ok)throw new Error(data.error||'Could not remove photo.');
     state.profile.hasAvatar=false;state.profile.avatarVersion=data.avatarVersion;
     toast('Profile photo removed.');render();
   }catch(error){toast(error.message||'Could not remove photo.');}
 }

