let state=structuredClone(base);
let serverReady=false;
let pendingSave=Promise.resolve();
const store=()=>{
  // Local data cache is for display only. SQLite is the source of truth.
  if (!serverReady) return;
  const payload=JSON.stringify({profile:state.profile,grades:state.grades,applications:state.applications,campaigns:state.campaigns,chat:state.chat});
  pendingSave=pendingSave.then(async ()=>{
    const r=await fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:payload});
    if(!r.ok)throw new Error('Database save failed: '+r.status);
  }).catch(err=>{console.error(err);toast('SQLite save failed — check the terminal');});
};
async function boot(){
  try {
    const r=await fetch('/api/bootstrap',{cache:'no-store'});
    if(!r.ok)throw new Error('Backend returned '+r.status);
    const data=await r.json();
    institutions=data.institutions;
    programmes=data.programmes;
    const ui=JSON.parse(sessionStorage.getItem('edupath-sqlite-ui')||'{}');
    state={...base,...data.state,role:ui.role||base.role,page:ui.page||base.page,theme:ui.theme||'light',
      profile:data.state.profile,grades:data.state.grades,applications:data.state.applications,
      campaigns:data.state.campaigns,chat:data.state.chat};
    serverReady=true;
    render();
  }catch(err){
    document.getElementById('main').innerHTML='<div class="container-xl py-5"><div class="alert alert-danger"><b>SQLite backend unavailable.</b> Start the app using <code>Start-EduPath-SQLite.bat</code>, then refresh. Details: '+esc(err.message)+'</div></div>';
  }
}
